import { readFileSync, writeFileSync } from "node:fs";
import { load as loadCheerio } from "cheerio/slim";
import { toMarkdown } from "./convert.mjs";
import { validate } from "./validate.mjs";

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg.startsWith("--")) {
      args[arg.slice(2)] = argv[i + 1];
      i += 1;
    }
  }
  return args;
}

async function loadRecipe(path) {
  const source = readFileSync(path, "utf8");
  const encoded = Buffer.from(source, "utf8").toString("base64");
  return import(`data:text/javascript;base64,${encoded}`);
}

// Recipe modules are plain JS (the real dynamic worker loads recipe source
// directly, unbundled — see pipeline/src/runtime/run.ts), so a .ts recipe file
// with no type annotations imports fine as a data: URL without any TS tooling.
async function main() {
  const args = parseArgs(process.argv.slice(2));
  const mode = args.mode ?? "inner";
  const articlePath = args.article;
  const recipePath = args.recipe;
  const outPath = args.out;

  const html = readFileSync(articlePath, "utf8");
  const recipe = await loadRecipe(recipePath);

  const $ = loadCheerio(html);
  const container = $(recipe.container).first();
  const containerElement = container.get(0);
  if (containerElement == null) {
    console.error(JSON.stringify({ ok: false, report: [`container "${recipe.container}" matches nothing`] }, null, 2));
    process.exit(1);
  }

  const boundToMarkdown = (element) => toMarkdown(element, mode);
  let output;
  try {
    output = recipe.extract($, boundToMarkdown);
  } catch (error) {
    console.error(JSON.stringify({ ok: false, report: [`the recipe crashed: ${error.stack ?? String(error)}`] }, null, 2));
    process.exit(1);
  }

  const units = output.units.map((unit) => {
    const element = Array.isArray(unit.element) ? unit.element[0] : unit.element?.get ? unit.element.get(0) : unit.element;
    return { ...unit, element };
  });

  const problems = validate({
    $,
    container: containerElement,
    units,
    ignores: recipe.ignores ?? [],
    inventory: recipe.inventory ?? [],
    checkOrphanedLiEnabled: args["orphaned-li-check"] !== "off",
  });

  const serializableUnits = units.map(({ element, ...rest }) => rest);

  const result =
    problems.length > 0
      ? { ok: false, report: problems }
      : { ok: true, title: output.title, units: serializableUnits };

  if (outPath) {
    writeFileSync(outPath, JSON.stringify(result, null, 2));
  }
  console.log(JSON.stringify(result, null, 2));
  process.exit(result.ok ? 0 : 1);
}

main();

