const UNREADABLE_TAGS = new Set(["script", "style", "noscript", "template", "head"]);

function describeElement($, element) {
  const classes = $(element).attr("class");
  return classes ? `<${element.name} class="${classes}">` : `<${element.name}>`;
}

function collectReadableText($, root) {
  const leftovers = [];
  $(root)
    .find("*")
    .each((_index, node) => {
      if (UNREADABLE_TAGS.has(node.name)) {
        return;
      }
      const own = $(node)
        .contents()
        .filter((_i, child) => child.type === "text")
        .text()
        .replace(/\s+/g, " ")
        .trim();
      if (own.length > 0) {
        leftovers.push(`${describeElement($, node)} "${own.slice(0, 120)}"`);
      }
    });
  return leftovers;
}

function ignoredElements($, container, ignores) {
  const ignored = new Set();
  const combined = ignores.map((ignore) => ignore.selector).join(",");
  if (combined.length > 0) {
    $(container)
      .find(combined)
      .each((_index, node) => {
        ignored.add(node);
      });
  }
  return ignored;
}

function checkInventory($, container, units, inventory, ignored, problems) {
  if (inventory.length === 0) {
    return;
  }
  const covered = new Set(units.map((unit) => unit.element));
  for (const unit of units) {
    $(unit.element)
      .find("*")
      .each((_index, node) => {
        covered.add(node);
      });
  }
  for (const entry of inventory) {
    $(container)
      .find(entry.selector)
      .each((_index, node) => {
        covered.add(node);
      });
  }
  const unexpected = [];
  $(container)
    .find("*")
    .each((_index, node) => {
      if (UNREADABLE_TAGS.has(node.name) || covered.has(node) || ignored.has(node)) {
        return;
      }
      unexpected.push(describeElement($, node));
    });
  if (unexpected.length > 0) {
    problems.push(
      `element kinds inside the container are neither units, ignored, nor declared in the inventory: ${unexpected.slice(0, 12).join(", ")}`,
    );
  }
}

function checkLeftoverText($, container, units, inventory, ignored, problems) {
  const removable = units.map((unit) => unit.element);
  for (const entry of inventory) {
    if (entry.role !== "title") {
      continue;
    }
    $(container)
      .find(entry.selector)
      .each((_index, node) => {
        removable.push(node);
      });
  }
  for (const element of removable) {
    $(element).remove();
  }
  for (const element of ignored) {
    $(element).remove();
  }
  const leftover = collectReadableText($, container);
  if (leftover.length > 0) {
    problems.push(`readable text is left after the units and ignores: ${leftover.join(" | ")}`);
  }
}

function checkMarkdown(units, problems) {
  units.forEach((unit, position) => {
    if (unit.type === "image") {
      return;
    }
    if (unit.display.trim().length === 0) {
      problems.push(`unit ${position} carries empty markdown`);
    }
  });
}

// New for this spike: a recipe that hands toMarkdown one <li> at a time
// (instead of the whole <ul>/<ol>) produces a unit backed by an orphaned
// list-item element — the thing the "list is always one unit" rule forbids.
function checkOrphanedLi(units, problems) {
  units.forEach((unit, position) => {
    if (unit.element?.name === "li") {
      problems.push(`unit ${position} is an orphaned <li> not wrapped in an <ol>/<ul>`);
    }
  });
}

// $ here must be the SAME cheerio instance the recipe's extract($) ran
// against — clone it before calling validate if you still need the
// original tree afterward, since checkLeftoverText mutates it by removing
// unit and ignored elements.
export function validate({ $, container, units, ignores, inventory, checkOrphanedLiEnabled = true }) {
  const problems = [];
  const ignored = ignoredElements($, container, ignores);
  checkMarkdown(units, problems);
  if (checkOrphanedLiEnabled) {
    checkOrphanedLi(units, problems);
  }
  checkInventory($, container, units, inventory, ignored, problems);
  checkLeftoverText($, container, units, inventory, ignored, problems);
  return problems;
}

import re

from markdown_it import MarkdownIt
from markdown_it.tree import SyntaxTreeNode

_LIST_ITEM = re.compile(r"^\s*([-*+]|\d+\.)\s+")
_FENCE = re.compile(r"^[ ]{0,3}(```|~~~)")
_TABLE_ROW = re.compile(r"^\s*\|.*\|\s*$")
_HEADING = re.compile(r"^\s*#{1,6}\s+")

_TAG_SHAPE = r"</?([A-Za-z][A-Za-z0-9-]*(?:\s[^<>]*?)?)\s*/?>"
_SPOKEN_HTML_TAG = re.compile(rf"\\?{_TAG_SHAPE}")

_md = MarkdownIt("commonmark").enable("table")

_ORDINALS = [
    "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
    "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen",
    "Eighteen", "Nineteen", "Twenty",
]


def is_cruft(text: str, title_norm: str) -> bool:
    core = _LIST_ITEM.sub("", _HEADING.sub("", text)).strip()

    if title_norm and core.lower() == title_norm:
        return True

    return is_unspeakable(core)


def to_spoken(unit: str, list_mode: str = "current") -> str:
    """Render one markdown unit to clean spoken text. list_mode "current" reads a whole
    list (however many items) as one run-on sentence, same as every other unit. list_mode
    "items" splits it: each top-level and nested item becomes its own sentence, in document
    order, an ordered item's sentence prefixed with its spoken number ("One. ...")."""
    if _FENCE.match(unit):
        return "Code sample."

    if _TABLE_ROW.match(unit.lstrip().split("\n", 1)[0]):
        return _table_to_spoken(unit)

    if list_mode == "items" and _is_list(unit):
        return _list_to_spoken_items(unit)

    out: list[str] = []

    for tok in _md.parse(unit):
        if tok.type != "inline":
            continue

        for child in tok.children or []:
            if child.type in ("text", "code_inline"):
                out.append(child.content)
            elif child.type in ("softbreak", "hardbreak"):
                out.append(" ")

    return sanitize_spoken("".join(out))


def _is_list(unit: str) -> bool:
    for line in unit.split("\n"):
        stripped = line.strip()
        if stripped == "":
            continue
        return bool(_LIST_ITEM.match(line))
    return False


def _list_to_spoken_items(unit: str) -> str:
    """Walk the parsed tree for one list unit and emit one sentence per list item, an
    item's own text flushed before its nested sub-list is walked (so the item that
    introduces a nested list reads before its children, not after), an ordered item's
    sentence prefixed with its spoken position ("One.") or its literal number past
    twenty. A multi-paragraph item's paragraphs are joined into that one sentence."""
    tree = SyntaxTreeNode(_md.parse(unit))
    sentences: list[str] = []

    def collect_own_text(node, parts: list[str]) -> None:
        if node.type in ("bullet_list", "ordered_list"):
            return
        if node.type == "inline":
            for child in node.children:
                if child.type in ("text", "code_inline"):
                    parts.append(child.content)
                elif child.type in ("softbreak", "hardbreak"):
                    parts.append(" ")
            return
        for child in node.children:
            collect_own_text(child, parts)

    def walk(list_node) -> None:
        ordered = list_node.type == "ordered_list"
        number = int(list_node.attrs.get("start", 1)) if ordered else 0
        for item in list_node.children:
            parts: list[str] = []
            collect_own_text(item, parts)
            text = sanitize_spoken("".join(parts)).rstrip(".")
            if text != "":
                if ordered:
                    prefix = _ORDINALS[number - 1] if 1 <= number <= len(_ORDINALS) else str(number)
                    sentences.append(f"{prefix}. {text}.")
                else:
                    sentences.append(f"{text}.")
            if ordered:
                number += 1
            for child in item.children:
                if child.type in ("bullet_list", "ordered_list"):
                    walk(child)

    for top in tree.children:
        if top.type in ("bullet_list", "ordered_list"):
            walk(top)

    return " ".join(sentences)


def is_unspeakable(spoken: str) -> bool:
    return not any(c.isalnum() for c in spoken)


def sanitize_spoken(text: str) -> str:
    text = _SPOKEN_HTML_TAG.sub(r"\1", text)
    text = re.sub(r"\*\*|__|\*|`", " ", text)
    text = re.sub(r"\s+([,.;:!?])", r"\1", text)

    return re.sub(r"\s+", " ", text).strip()


def _table_to_spoken(table: str) -> str:
    rows: list[list[str]] = []
    cur: list[str] = []

    for tok in _md.parse(table):
        if tok.type == "inline":
            cur.append(tok.content)
        elif tok.type == "tr_close":
            rows.append(cur)
            cur = []

    if len(rows) < 2:
        return sanitize_spoken(" ".join(rows[0])) if rows else ""

    header = rows[0]
    return sanitize_spoken(
        ". ".join(
            ", ".join(f"{header[i]}: {cell}" for i, cell in enumerate(row) if i < len(header))
            for row in rows[1:]
        )
        + "."
    )


def image_to_spoken(alt: str) -> str:
    alt = alt.strip()
    return f"Image: {alt}." if alt else "Image with no description."


def code_to_spoken() -> str:
    return "Code sample."

