export const container = "article";

export const ignores = [
  { selector: "sup#fnref1, sup#fnref2", reason: "footnote reference markers" },
  { selector: "ol.footnotes", reason: "footnote bodies" },
  { selector: ".share-buttons", reason: "share row" },
  { selector: ".newsletter-cta", reason: "newsletter signup chrome" },
  { selector: ".sponsor-box", reason: "sponsor ad" },
  { selector: ".ad-slot", reason: "advertisement slot" },
  { selector: "aside.pullquote", reason: "decorative pull-quote duplicating body text already present" },
  { selector: "aside.read-more", reason: "cross-link chrome, not article content" },
  { selector: "img[width='1'][height='1']", reason: "tracking pixel" },
  { selector: "svg", reason: "decorative diagram already described by the surrounding prose" },
  { selector: "svg *", reason: "descendant marks of the decorative diagram" },
  { selector: "hr", reason: "visual divider" },
  { selector: "button", reason: "share/subscribe UI controls, not article content" },
];

export const inventory = [
  { selector: "h1", role: "title" },
  { selector: "h2, h3, h4, h5, h6", role: "unit" },
  { selector: "p", role: "unit" },
  { selector: "blockquote", role: "unit" },
  { selector: "div.quote", role: "unit" },
  { selector: "ul, ol", role: "unit" },
  { selector: "li", role: "inline" },
  { selector: "dl", role: "unit" },
  { selector: "dt, dd", role: "inline" },
  { selector: "table", role: "unit" },
  { selector: "thead, tbody, tr", role: "wrapper" },
  { selector: "th, td", role: "inline" },
  { selector: "figure", role: "wrapper" },
  { selector: "figcaption", role: "unit" },
  { selector: "img", role: "unit" },
  { selector: "math", role: "unit" },
  { selector: "pre", role: "unit" },
  { selector: "div.listing", role: "unit" },
  { selector: "div.listing span", role: "inline" },
  { selector: "details", role: "wrapper" },
  { selector: "summary", role: "unit" },
  { selector: "em, strong, a, mark, del, cite, footer, code, kbd, br, input", role: "inline" },
];

const stripSup = ($clone, $) => {
  $clone.find("sup#fnref1, sup#fnref2").remove();
  return $clone;
};

const swapMath = ($clone, $) => {
  $clone.find("math").each((_, m) => {
    const $m = $(m);
    $m.replaceWith(`$${$m.attr("alttext") ?? ""}$`);
  });
  return $clone;
};

const sanitizedClone = (el, $) => swapMath(stripSup($(el).clone(), $), $);

export function extract($, toMarkdown) {
  const article = $("article").first();
  const title = article.find("h1").first().text().trim();
  const units = [];

  const pushParagraph = (el) => {
    const display = toMarkdown(sanitizedClone(el, $));
    units.push({ type: "paragraph", display, element: el });
  };

  const pushCode = (el) => {
    const display = toMarkdown(sanitizedClone(el, $));
    units.push({ type: "code", display, element: el });
  };

  article.children().each((_, el) => {
    const $el = $(el);
    const tag = el.tagName?.toLowerCase();

    if (tag === "h1") return;
    if ($el.is(".share-buttons, .newsletter-cta, .sponsor-box, .ad-slot")) return;
    if ($el.is("aside.pullquote, aside.read-more")) return;
    if (tag === "hr") return;
    if (tag === "svg") return;
    if ($el.is("ol.footnotes")) return;

    if (["h2", "h3", "h4", "h5", "h6", "p", "blockquote", "dl"].includes(tag)) {
      pushParagraph(el);
      return;
    }

    if (tag === "div" && $el.hasClass("quote")) {
      pushParagraph(el);
      return;
    }

    if (tag === "ul" || tag === "ol") {
      pushParagraph(el);
      return;
    }

    if (tag === "table") {
      const $clone = $el.clone();
      if ($clone.find("thead").length === 0) {
        const $firstRow = $clone.find("tr").first();
        const $thead = $("<thead></thead>");
        $thead.append($firstRow.clone());
        $firstRow.remove();
        $clone.prepend($thead);
      }
      units.push({ type: "paragraph", display: toMarkdown($clone), element: el });
      return;
    }

    if (tag === "figure") {
      const $img = $el.find("img").first();

      if ($img.length > 0) {
        units.push({
          type: "image",
          src: $img.attr("src") ?? null,
          alt: $img.attr("alt") ?? "",
          element: $img.get(0),
        });
      }

      const $figcaption = $el.find("figcaption").first();
      if ($figcaption.length > 0) {
        pushParagraph($figcaption.get(0));
      }
      return;
    }

    if (tag === "img") {
      if ($el.attr("width") === "1" && $el.attr("height") === "1") return;
      units.push({
        type: "image",
        src: $el.attr("data-src") ?? $el.attr("src") ?? null,
        alt: $el.attr("alt") ?? "",
        element: el,
      });
      return;
    }

    if (tag === "div" && $el.hasClass("listing")) {
      const lines = [];
      $el.find(".line").each((_, line) => {
        lines.push($(line).text());
      });
      const $pre = $("<pre><code></code></pre>");
      $pre.find("code").text(lines.join("\n"));
      units.push({ type: "code", display: toMarkdown($pre), element: el });
      return;
    }

    if (tag === "pre") {
      pushCode(el);
      return;
    }

    if (tag === "math") {
      const alttext = $el.attr("alttext") ?? "";
      const $p = $(`<p>$$${alttext}$$</p>`);
      units.push({ type: "paragraph", display: toMarkdown($p), element: el });
      return;
    }

    if (tag === "details") {
      const $summary = $el.find("summary").first();
      if ($summary.length > 0) {
        pushParagraph($summary.get(0));
      }
      $el.children("p").each((_, p) => {
        pushParagraph(p);
      });
      return;
    }
  });

  return { title, units };
}

export const RECIPE_CONTRACT = `
A recipe is one JavaScript ES module that imports nothing and exports, by name:

- container: a selector string naming the element that holds the article; everything outside it is site chrome.
- ignores: a list of { selector, reason } for elements deliberately excluded (ads, date stamps, share rows). Every recipe excludes footnote markers and footnote bodies: declare them here.
- inventory: a list of { selector, role } naming every element kind the container carries, role being one of unit (becomes an extracted unit), inline (content inside a unit), wrapper (structural container carrying no content of its own), or title.
- extract($, toMarkdown): builds the article from the parsed document.
  - $ is a Cheerio document of the article. Read it without changing it; prepare clones instead.
  - toMarkdown(element) converts an element to markdown with the fixed converter; every paragraph and code unit's display comes from it.
  - It returns { title, units } where each unit is one of:
    { type: "paragraph", display, element }
    { type: "code", display, element }
    { type: "image", src, alt, element }
  - Units come back in document order, one element per unit, never overlapping.
  - An image the article carries is always emitted, even when its src cannot be resolved; alt is exactly what the page presents and is never invented.

Structural preparation (building a thead for a bare table, swapping MathML for its alttext LaTeX, wrapping a span-built listing in a pre, removing footnote subtrees) happens on a cloned element you then pass to toMarkdown.
`;

export const REPLY_CONTRACT = `
The extract tool's recipe argument is the module source itself, never this envelope: the json below belongs only to your final reply.

Your final reply is one fenced json block and nothing else after it:

- a settled script: \`{"kind": "script", "source": "<the full recipe module source>"}\`
- the page is not an article: \`{"kind": "not-article"}\`
- you give up: \`{"kind": "gave-up", "reason": "<why>"}\`

Never include the extracted units in the reply: the recipe itself is re-run deterministically to produce them.
`;

function articleSection(html: string): string {
  return `The article's html:

\`\`\`html
${html}
\`\`\``;
}

export function authorInstruction(maxTurns: number, html: string): string {
  return `You author extraction recipes for one article at a time.

Write the whole recipe on your first turn and let the tool find the mistakes. Skim the html below for the container and the element kinds inside it, write the complete module, call extract, read the report, rewrite whatever it names, call extract again. Repeat until the report is clean, then reply with the settled script.

Guessing and correcting is faster than getting it right up front, and the report is a better reader of the markup than you are. Do not study the html element by element, do not plan the recipe in prose, and do not build it up a selector at a time across several calls. A first draft that fails validation is the expected first turn.

You have about ${maxTurns} turns for the whole loop; settle well before that.

A page that is not an article (a homepage, a 200-status error page, a login wall) gets the not-article verdict, from you or from the tool's report judging the same.

${RECIPE_CONTRACT}
${REPLY_CONTRACT}
${articleSection(html)}`;
}

export function revisorInstruction(maxTurns: number, html: string): string {
  return `You revise an existing extraction recipe that failed one article.

The standing instruction is additive: keep the recipe's previous assumptions and add what this article needs. A wholesale markup change is the exception: when you judge the domain was redesigned, you may rewrite the recipe outright.

Write the whole revised recipe on your first turn and let the tool find the mistakes: skim the html below for what the recipe missed, apply your fix, call extract, read the report, rewrite whatever it names, call extract again. Repeat until the report is clean, then reply with the settled script.

Do not study the html element by element, do not plan the revision in prose, and do not change one selector per call. A draft that still fails validation is the expected first turn.

You have about ${maxTurns} turns for the whole loop; settle well before that.

A page that is not an article (a 200-status error page, a login wall) gets the not-article verdict, and no version is written: the recipe stands.

${RECIPE_CONTRACT}
${REPLY_CONTRACT}
${articleSection(html)}`;
}

export function authorMessage(domain: string, report: string[] | null = null): string {
  const failure =
    report == null
      ? ""
      : `\n\nThe previous authoring attempt failed this article:\n${report.map((line) => `- ${line}`).join("\n")}`;
  return (
    `Author the extraction recipe for ${domain} from the article in your instructions. The extract tool runs candidate recipes against that same article.` +
    failure
  );
}

export function revisionMessage(domain: string, report: string[], recipeSource: string): string {
  return `The current recipe for ${domain} failed this article.

Validator report:
${report.map((line) => `- ${line}`).join("\n")}

Current recipe:
${recipeSource}

The article in your instructions is the one that failed, and the extract tool runs candidate recipes against it. Revise the recipe until the report is clean, then reply with the settled script.`;
}

import random
from typing import Protocol

import modal

from ..config import settings
from ..models.item import ItemStatus
from ..schemas.tts import SynthesisResult

# Curated Kokoro (American-English) voices for the random default; low-grade voices
# are excluded so an un-voiced item always sounds good. Any voice remains explicitly
# requestable — this pool only governs the fallback when none is given.
VOICE_POOL = [
    "af_heart", "af_bella", "af_sarah", "af_sky", "af_aoede", "af_alloy", "af_nova",
    "am_fenrir", "am_michael", "am_puck",
]


def pick_voice() -> str:
    return random.choice(VOICE_POOL)


def spawn_synthesis(paragraphs: list[str], voice: str) -> str:
    """Kick off eager generation on Modal; return the FunctionCall id to persist."""
    kokoro = modal.Cls.from_name(settings.modal_app, settings.modal_cls)
    call = kokoro().synthesize.spawn(paragraphs=paragraphs, voice=voice)
    return call.object_id


def poll_synthesis(call_id: str) -> tuple[ItemStatus, SynthesisResult | str | None]:
    """Lazily resolve a spawned job. Returns one of:
    (ItemStatus.READY, SynthesisResult) | (ItemStatus.GENERATING, None) | (ItemStatus.FAILED, error_str).

    The running-vs-crashed distinction is load-bearing: a still-running job raises
    TimeoutError on get(timeout=0), while a crashed remote job re-raises its exception
    here — so a running job is never misclassified as failed.
    """
    fc = modal.FunctionCall.from_id(call_id)
    try:
        result = fc.get(timeout=0)
    except TimeoutError:
        return ItemStatus.GENERATING, None
    except Exception as e:
        return ItemStatus.FAILED, f"{type(e).__name__}: {e}"

    return ItemStatus.READY, SynthesisResult.model_validate(result)


class Synthesizer(Protocol):
    """Render spoken paragraphs to audio on a remote host with no broker: ``spawn`` returns a
    handle to persist, ``resolve`` reads it lazily on poll. The API never imports the TTS code
    (invariant 5) — a Synthesizer only spawns and resolves it remotely."""

    def spawn(self, paragraphs: list[str], voice: str) -> str: ...

    def resolve(self, call_id: str) -> tuple[ItemStatus, SynthesisResult | str | None]: ...


class ModalSynthesizer:
    """The Modal-backed ``Synthesizer``: spawn through the class handle, resolve with a
    non-blocking get whose exception type tells a running job from a crashed one. Both calls are
    synchronous Modal-client calls, bridged through the threadpool at the step."""

    def spawn(self, paragraphs: list[str], voice: str) -> str:
        return spawn_synthesis(paragraphs, voice)

    def resolve(self, call_id: str) -> tuple[ItemStatus, SynthesisResult | str | None]:
        return poll_synthesis(call_id)

