import * as domino from "@mixmark-io/domino";
import { load as loadCheerio } from "cheerio/slim";
import TurndownService from "turndown";

const turndown = new TurndownService({
  codeBlockStyle: "fenced",
  headingStyle: "atx",
  hr: "---",
  bulletListMarker: "-",
});

const globals = globalThis;
globals.document ??= domino.createDocument("<html><body></body></html>");
globals.Node ??= domino.impl.Node;
globals.Element ??= domino.impl.Element;
globals.NodeFilter ??= {
  SHOW_ELEMENT: 1,
  SHOW_TEXT: 4,
  SHOW_COMMENT: 8,
  FILTER_ACCEPT: 1,
  FILTER_REJECT: 2,
  FILTER_SKIP: 3,
};

const $render = loadCheerio("");

// mode "inner" mirrors the current entry.ts: $render(element).html() takes the
// element's innerHTML, so a wrapper tag (e.g. <ul>) that the recipe itself passed
// in is dropped before turndown ever sees it. mode "outer" serializes the element
// itself, keeping that wrapper.
export function toMarkdown(element, mode = "inner") {
  const html = mode === "outer" ? ($render.html(element) ?? "") : ($render(element).html() ?? "");
  const document = domino.createDocument(`<body>${html}</body>`);
  const markdown = turndown.turndown(document.body);
  return markdown.trim();
}

export { loadCheerio };

