export const container = "article";

export const ignores = [
  { selector: "div.share-buttons, div.share-buttons *", reason: "share/social buttons, not article content" },
  { selector: "div.newsletter-cta, div.newsletter-cta *", reason: "newsletter signup chrome" },
  { selector: "div.sponsor-box, div.sponsor-box *", reason: "sponsor advertisement" },
  { selector: "div.ad-slot, div.ad-slot *", reason: "advertisement slot" },
  { selector: "aside.read-more, aside.read-more *", reason: "cross-promotional read-more link, not article content" },
  { selector: "aside.pullquote", reason: "pull quote duplicating body text; would double-read for a listener" },
  { selector: 'sup[id^="fnref"]', reason: "footnote markers" },
  { selector: "ol.footnotes, ol.footnotes *", reason: "footnote bodies" },
  { selector: "hr", reason: "thematic break, carries no readable content" },
  { selector: "p:contains(\"❦\")", reason: "decorative section-break glyph, not readable prose" },
  {
    selector: "svg, svg *",
    reason: "inline vector diagram with no image src; its content duplicates the preceding figure",
  },
  { selector: 'img[width="1"][height="1"]', reason: "1x1 tracking pixel, not a content image" },
];

export const inventory = [
  { selector: "h1", role: "title" },
  { selector: "p", role: "unit" },
  { selector: "h2, h3, h4, h5, h6", role: "unit" },
  { selector: "blockquote", role: "unit" },
  { selector: "ul, ol", role: "unit" },
  { selector: "dl", role: "unit" },
  { selector: "table", role: "unit" },
  { selector: "pre", role: "unit" },
  { selector: "details", role: "unit" },
  { selector: "figcaption", role: "unit" },
  { selector: "img", role: "unit" },
  { selector: 'math[display="block"]', role: "unit" },
  { selector: 'math:not([display="block"])', role: "inline" },
  { selector: "figure", role: "wrapper" },
  { selector: "li, dt, dd, thead, tbody, tr, th, td, summary", role: "wrapper" },
  { selector: "em, strong, del, mark, sup, a, code, kbd, br, cite, footer, span", role: "inline" },
];

export function extract($, toMarkdown) {
  const root = $(container).first();
  const title = root.find("h1").first().text().trim();

  const units = [];

  const toWrappedMarkdown = (content) => {
    const div = $("<div>");
    div.append(content);
    return toMarkdown(div.get(0));
  };

  const paragraph = (el) => ({ type: "paragraph", display: toMarkdown(el), element: el });

  const paragraphWrapped = (el) => ({
    type: "paragraph",
    display: toWrappedMarkdown($(el).clone()),
    element: el,
  });

  const codeUnit = (el, content) => ({ type: "code", display: toWrappedMarkdown(content), element: el });

  const image = (el) => {
    const $el = $(el);
    return {
      type: "image",
      src: $el.attr("data-src") ?? $el.attr("src") ?? null,
      alt: $el.attr("alt") ?? "",
      element: el,
    };
  };

  root.contents().each((_index, node) => {
    if (node.type !== "tag") {
      return;
    }
    const $node = $(node);

    if ($node.is("h1")) {
      return;
    }
    if (
      $node.is(
        "div.share-buttons, div.newsletter-cta, div.sponsor-box, div.ad-slot, aside.pullquote, aside.read-more, hr, ol.footnotes, svg",
      )
    ) {
      return;
    }
    if ($node.is('img[width="1"][height="1"]')) {
      return;
    }
    if ($node.is("p") && $node.text().trim() === "❦") {
      return;
    }

    if ($node.is("h2, h3, h4, h5, h6")) {
      units.push(paragraphWrapped(node));
      return;
    }

    if ($node.is("ul") && $node.find("pre").length > 0) {
      $node.children("li").each((_i, li) => {
        $(li)
          .contents()
          .each((_j, child) => {
            if (child.type !== "tag") {
              return;
            }
            if (child.name === "p") {
              units.push(paragraph(child));
            } else if (child.name === "pre") {
              units.push(codeUnit(child, $(child).clone()));
            }
          });
      });
      return;
    }

    if ($node.is("ul") && $node.find('input[type="checkbox"]').length > 0) {
      const clone = $node.clone();
      clone.find('input[type="checkbox"]').each((_i, input) => {
        const $input = $(input);
        $input.replaceWith($input.is("[checked]") ? "[x] " : "[ ] ");
      });
      units.push({ type: "paragraph", display: toWrappedMarkdown(clone), element: node });
      return;
    }

    if ($node.is("table")) {
      const clone = $node.clone();
      if (clone.find("thead").length === 0) {
        const firstRow = clone.find("tbody > tr").first();
        const headerCellsHtml = firstRow.children("td").map((_i, td) => $(td).html()).get();
        firstRow.remove();
        const headRow = $("<tr>");
        headerCellsHtml.forEach((html) => {
          const th = $("<th>");
          th.html(html);
          headRow.append(th);
        });
        const thead = $("<thead>");
        thead.append(headRow);
        clone.prepend(thead);
      }
      units.push({ type: "paragraph", display: toWrappedMarkdown(clone), element: node });
      return;
    }

    if ($node.is("blockquote, ul, ol, dl, details")) {
      units.push(paragraphWrapped(node));
      return;
    }

    if ($node.is("div.quote")) {
      units.push(paragraph(node));
      return;
    }

    if ($node.is("figure")) {
      const img = $node.find("img").get(0);
      if (img != null) {
        units.push(image(img));
      }
      const caption = $node.find("figcaption").get(0);
      if (caption != null) {
        units.push(paragraph(caption));
      }
      return;
    }

    if ($node.is("img")) {
      units.push(image(node));
      return;
    }

    if ($node.is("pre")) {
      const code = $("<code>").text($node.text());
      const pre = $("<pre>").append(code);
      units.push(codeUnit(node, pre));
      return;
    }

    if ($node.is('math[display="block"]')) {
      const alt = $node.attr("alttext") ?? "";
      units.push({ type: "paragraph", display: toMarkdown($("<p>").text(alt).get(0)), element: node });
      return;
    }

    if ($node.is("div.listing")) {
      const lines = $node
        .find("span.line")
        .map((_i, line) => $(line).text())
        .get();
      const code = $("<code>").text(lines.join("\n"));
      const pre = $("<pre>").append(code);
      units.push(codeUnit(node, pre));
      return;
    }

    if ($node.is("p")) {
      const hasFootnoteRef = $node.find('sup[id^="fnref"]').length > 0;
      const hasMath = $node.find("math").length > 0;
      if (!hasFootnoteRef && !hasMath) {
        units.push(paragraph(node));
        return;
      }
      const clone = $node.clone();
      clone.find('sup[id^="fnref"]').remove();
      clone.find("math").each((_i, math) => {
        $(math).replaceWith($(math).attr("alttext") ?? "");
      });
      units.push({ type: "paragraph", display: toMarkdown(clone.get(0)), element: node });
      return;
    }
  });

  return { title, units };
}

import re

from markdown_it import MarkdownIt
from markdown_it.tree import SyntaxTreeNode

_LIST_ITEM = re.compile(r"^\s*([-*+]|\d+\.)\s+")
_FENCE = re.compile(r"^[ ]{0,3}(```|~~~)")
_TABLE_ROW = re.compile(r"^\s*\|.*\|\s*$")
_HEADING = re.compile(r"^\s*#{1,6}\s+")

_TAG_SHAPE = r"</?([A-Za-z][A-Za-z0-9-]*(?:\s[^<>]*?)?)\s*/?>"
_SPOKEN_HTML_TAG = re.compile(rf"\\?{_TAG_SHAPE}")

_md = MarkdownIt("commonmark").enable("table")

_ORDINALS = [
    "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
    "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen",
    "Eighteen", "Nineteen", "Twenty",
]


def is_cruft(text: str, title_norm: str) -> bool:
    core = _LIST_ITEM.sub("", _HEADING.sub("", text)).strip()

    if title_norm and core.lower() == title_norm:
        return True

    return is_unspeakable(core)


def to_spoken(unit: str, list_mode: str = "current") -> str:
    """Render one markdown unit to clean spoken text. list_mode "current" reads a whole
    list (however many items) as one run-on sentence, same as every other unit. list_mode
    "items" splits it: each top-level and nested item becomes its own sentence, in document
    order, an ordered item's sentence prefixed with its spoken number ("One. ...")."""
    if _FENCE.match(unit):
        return "Code sample."

    if _TABLE_ROW.match(unit.lstrip().split("\n", 1)[0]):
        return _table_to_spoken(unit)

    if list_mode == "items" and _is_list(unit):
        return _list_to_spoken_items(unit)

    out: list[str] = []

    for tok in _md.parse(unit):
        if tok.type != "inline":
            continue

        for child in tok.children or []:
            if child.type in ("text", "code_inline"):
                out.append(child.content)
            elif child.type in ("softbreak", "hardbreak"):
                out.append(" ")

    return sanitize_spoken("".join(out))


def _is_list(unit: str) -> bool:
    for line in unit.split("\n"):
        stripped = line.strip()
        if stripped == "":
            continue
        return bool(_LIST_ITEM.match(line))
    return False


def _list_to_spoken_items(unit: str) -> str:
    """Walk the parsed tree for one list unit and emit one sentence per list item, an
    item's own text flushed before its nested sub-list is walked (so the item that
    introduces a nested list reads before its children, not after), an ordered item's
    sentence prefixed with its spoken position ("One.") or its literal number past
    twenty. A multi-paragraph item's paragraphs are joined into that one sentence."""
    tree = SyntaxTreeNode(_md.parse(unit))
    sentences: list[str] = []

    def collect_own_text(node, parts: list[str]) -> None:
        if node.type in ("bullet_list", "ordered_list"):
            return
        if node.type == "inline":
            for child in node.children:
                if child.type in ("text", "code_inline"):
                    parts.append(child.content)
                elif child.type in ("softbreak", "hardbreak"):
                    parts.append(" ")
            return
        for child in node.children:
