    header = rows[0]
    return sanitize_spoken(
        ". ".join(
            ", ".join(f"{header[i]}: {cell}" for i, cell in enumerate(row) if i < len(header))
            for row in rows[1:]
        )
        + ".",
        apply_steps_2_4,
    )


def image_to_spoken(alt: str) -> str:
    alt = alt.strip()
    return f"Image: {alt}." if alt else "Image with no description."


def code_to_spoken() -> str:
    return "Code sample."

